import {
	DEFAULT_ANONYMOUS_CHANNEL_TYPE,
	DEFAULT_CHANNEL_TYPE,
	getIframeBaseURL,
	MESSAGE_BIZ_ID,
} from "./constants";
import { slardar } from "@lark-apaas/internal-slardar";
import { DeviceDetector } from "./device-detector";
import { MessageBridge } from "./message-bridge";

import type { ChatPanel, WebSDKConfig } from "./types/config";

/**
 * IframeManager handles iframe creation and lifecycle
 *
 * iframe 采用自初始化模式：配置通过 URL hash 传入，iframe 加载后自行解析并渲染，
 * 与旧版 copilot iframe 的行为保持一致。宿主通过 postMessage 进行后续操作。
 */
export class IframeManager {
	private iframe: HTMLIFrameElement | null = null;
	private messageBridge: MessageBridge;
	private config: WebSDKConfig;
	private channelType: string;
	private root: HTMLElement;
	private deviceDetector: DeviceDetector | null = null;

	constructor(root: HTMLElement, config: WebSDKConfig) {
		this.root = root;
		this.config = config;
		const defaultChannel = config.anonymous
			? DEFAULT_ANONYMOUS_CHANNEL_TYPE
			: DEFAULT_CHANNEL_TYPE;
		this.channelType = config.common?.channelType || defaultChannel;
		this.messageBridge = new MessageBridge(getIframeBaseURL());
	}

	/**
	 * Initialize the iframe and establish communication
	 * 配置通过 URL hash 编码传入 iframe，iframe 加载后自行初始化
	 */
	async init(): Promise<ChatPanel> {
		const initStart = performance.now();

		// Auto-detect device if not explicitly provided
		if (!this.config.device) {
			this.deviceDetector = new DeviceDetector();
			this.config.device = this.deviceDetector.getDevice();
		}

		// Create iframe element
		this.iframe = document.createElement("iframe");
		this.iframe.src = this.buildIframeURL();
		this.iframe.style.width = "100%";
		this.iframe.style.height = "100%";
		this.iframe.style.border = "none";
		this.iframe.allow = "microphone; clipboard-write";

		// Attach to DOM
		this.root.appendChild(this.iframe);

		// Attach message bridge (开始监听消息)
		this.messageBridge.attach(this.iframe);

		// Setup event handlers (在 iframe 初始化完成之前就开始监听，确保不丢失事件)
		this.setupEventHandlers();

		// Listen for device changes and push updates to iframe
		if (this.deviceDetector) {
			this.deviceDetector.observe((newDevice) => {
				this.messageBridge.send("updateConfig", { device: newDevice });
			});
		}

		// Wait for iframe to finish initialization (iframe 自行读取 URL 配置并渲染，完成后发送 ready 事件)
		await this.waitForReady();

		// 上报 cui_init_total 耗时（iframe 创建 → init 完成）
		this.reportInitMetrics(initStart);

		// Return ChatPanel interface
		return this.createChatPanel();
	}

	/**
	 * Destroy the iframe and cleanup
	 */
	async destroy(): Promise<void> {
		try {
			await this.messageBridge.send("destroy");
		} catch {
			// Ignore errors during destroy
		}

		this.messageBridge.detach();

		if (this.deviceDetector) {
			this.deviceDetector.destroy();
			this.deviceDetector = null;
		}

		if (this.iframe?.parentNode) {
			this.iframe.parentNode.removeChild(this.iframe);
		}

		this.iframe = null;
	}

	/**
	 * 构建 iframe URL，将配置编码到 hash 中
	 * 格式: {baseURL}#{params} 其中 config 为 base64(JSON.stringify(configWithoutEvents))
	 *
	 * 鉴权说明：SDK 不参与 token 获取/传递。iframe 自行处理飞书登录流程，
	 * 允许用户在 iframe 中独立登录。匿名渠道跳过登录检查。
	 */
	private buildIframeURL(): string {
		const baseURL = getIframeBaseURL();

		// 移除 events（函数无法序列化）
		const {
			events: _events,
			anonymous: _anonymous,
			...configWithoutEvents
		} = this.config;
		// 注入 channelType/resourceType（SDK 内部控制，不暴露给消费者）
		// 补全 editor.skill 硬编码字段
		const editorConfig = configWithoutEvents.editor?.skill
			? {
					...configWithoutEvents.editor,
					skill: {
						type: "custom",
						builtinType: "unspecified",
						...configWithoutEvents.editor.skill,
					},
				}
			: configWithoutEvents.editor;

		const iframeConfig = {
			...configWithoutEvents,
			common: {
				...configWithoutEvents.common,
				channelType: this.channelType,
				resourceType:
					configWithoutEvents.common?.resourceType || this.channelType,
			},
			editor: editorConfig,
		};
		const configBase64 = btoa(encodeURIComponent(JSON.stringify(iframeConfig)));

		const params = new URLSearchParams({
			appKey: this.config.appKey,
			config: encodeURIComponent(configBase64),
		});

		return `${baseURL}#${params.toString()}`;
	}

	/**
	 * 等待 iframe 自行初始化完成后发送 ready 事件
	 */
	private waitForReady(): Promise<void> {
		return new Promise((resolve, reject) => {
			const timeout = setTimeout(() => {
				const error = new Error("Iframe ready timeout");
				slardar.captureException(error, { source: 'aily-web-sdk', module: 'iframe-ready' });
				reject(error);
			}, 30000);

			const checkMessage = (event: MessageEvent) => {
				if (
					event.data?.messageBizId === MESSAGE_BIZ_ID &&
					event.data?.type === "event" &&
					event.data?.eventName === "ready"
				) {
					clearTimeout(timeout);
					window.removeEventListener("message", checkMessage);
					resolve();
				}
			};

			window.addEventListener("message", checkMessage);
		});
	}

	private setupEventHandlers(): void {
		const { events } = this.config;
		if (!events) return;

		if (events.onReady) {
			this.messageBridge.onEvent("ready", events.onReady);
		}

		if (events.onError) {
			this.messageBridge.onEvent("error", (data: unknown) => {
				const msg = (data as { message?: string })?.message || "Unknown error";
				events.onError?.(new Error(msg));
			});
		}

		if (events.onMessage) {
			this.messageBridge.onEvent("onMessage", events.onMessage);
		}

		if (events.onInited) {
			this.messageBridge.onEvent(
				"inited",
				events.onInited as (data: unknown) => void,
			);
		}

		if (events.onInitedWithWelcome) {
			this.messageBridge.onEvent(
				"initedWithWelcome",
				events.onInitedWithWelcome,
			);
		}

		if (events.onClose) {
			this.messageBridge.onEvent("onClose", events.onClose);
		}
	}

	private reportInitMetrics(initStart: number): void {
		try {
			const cost = performance.now() - initStart;
			slardar.sendEvent({
				name: "cui_init_total",
				metrics: { cost },
				categories: {
					arch: "iframe-static",
					appKey: this.config.appKey,
					channelType: this.channelType,
				},
			});
		} catch {
			// 性能上报失败不影响功能
		}
	}

	private createChatPanel(): ChatPanel {
		return {
			sendMessage: async (data) => {
				await this.messageBridge.send("sendMessage", data);
			},
			clear: async () => {
				await this.messageBridge.send("clear");
			},
			cancelMessage: async (messageItem) => {
				await this.messageBridge.send("cancelMessage", messageItem);
			},
			clearAndStop: async () => {
				await this.messageBridge.send("clearAndStop");
			},
			updateWelcomeMessage: async () => {
				await this.messageBridge.send("updateWelcomeMessage");
			},
			updateConfig: async (config) => {
				await this.messageBridge.send("updateConfig", config);
			},
			observeSkill: async (skillId, name, skillType) => {
				await this.messageBridge.send("observeSkill", {
					skillId,
					name,
					skillType,
				});
			},
			setCurrentSkill: async (skill) => {
				await this.messageBridge.send("setCurrentSkill", skill);
			},
			destroy: async () => {
				await this.destroy();
			},
		};
	}
}
