/**
 * Constants for Aily Web SDK
 */

/** Message business ID for postMessage identification */
export const MESSAGE_BIZ_ID = 'cui-sdk-message' as const;
export const PARENT_ORIGIN_QUERY_KEY = '__parentOrigin' as const;

/** Iframe origins by environment */
export const IFRAME_ORIGIN: Record<string, string> = {
  production: 'https://aily.feishu.cn',
  staging: 'https://aily.feishu-pre.cn',
  boe: 'https://aily.feishu-boe.cn',
  development: 'http://localhost:8080',
};

/** Page paths for iframe apps */
export const CHAT_IFRAME_PATH = '/cui' as const;
export const AGENT_IFRAME_PATH = '/custom_agent/cui' as const;

/** Chat iframe base URLs by environment */
export const IFRAME_BASE_URL: Record<string, string> = {
  production: `${IFRAME_ORIGIN.production}${CHAT_IFRAME_PATH}`,
  staging: `${IFRAME_ORIGIN.staging}${CHAT_IFRAME_PATH}`,
  boe: `${IFRAME_ORIGIN.boe}${CHAT_IFRAME_PATH}`,
  development: `${IFRAME_ORIGIN.development}${CHAT_IFRAME_PATH}`,
};

/** Agent iframe base URLs by environment */
export const AGENT_IFRAME_BASE_URL: Record<string, string> = {
  production: `${IFRAME_ORIGIN.production}${AGENT_IFRAME_PATH}`,
  staging: `${IFRAME_ORIGIN.staging}${AGENT_IFRAME_PATH}`,
  boe: `${IFRAME_ORIGIN.boe}${AGENT_IFRAME_PATH}`,
  development: `${IFRAME_ORIGIN.development}${AGENT_IFRAME_PATH}`,
};

type IframeEnv = keyof typeof IFRAME_BASE_URL;

interface AilyWebSdkDebugConfig {
  iframeEnv?: string;
}

declare global {
  interface Window {
    __DEBUG__?: {
      ailyWebSdk?: AilyWebSdkDebugConfig;
      [key: string]: unknown;
    };
  }
}

function isIframeEnv(env?: string): env is IframeEnv {
  return Boolean(env && env in IFRAME_BASE_URL);
}

function resolveDebugIframeEnv(): IframeEnv | undefined {
  if (typeof window === 'undefined') {
    return undefined;
  }

  const debugIframeEnv = window.__DEBUG__?.ailyWebSdk?.iframeEnv;
  return isIframeEnv(debugIframeEnv) ? debugIframeEnv : undefined;
}

/**
 * Get iframe base URL based on environment
 */
function resolveIframeEnv(env?: string): IframeEnv {
  if (isIframeEnv(env)) {
    return env;
  }

  const debugIframeEnv = resolveDebugIframeEnv();
  if (debugIframeEnv) {
    return debugIframeEnv;
  }

  // Auto-detect based on hostname
  // MiaoDa 宿主域名: miaoda.feishu[-env].cn, *.aiforce[-env][-preview].bytedance.net, *.force-pre.feishuapp.net, *.fsapp.kundou.cn, *.aiforce.run, *.aiforce.cloud
  const hostname =
    typeof window !== 'undefined' ? window.location.hostname : '';

  if (hostname.includes('aiforce-boe')) {
    return 'boe';
  }
  if (
    hostname.includes('aiforce-pre') ||
    hostname.includes('force-pre.feishuapp.net') ||
    hostname.includes('fsapp.kundou.cn')
  ) {
    return 'staging';
  }

  return 'production';
}

export function getIframeBaseURL(env?: string): string {
  return IFRAME_BASE_URL[resolveIframeEnv(env)];
}

/**
 * Get agent iframe base URL based on environment
 */
export function getAgentIframeBaseURL(env?: string): string {
  return AGENT_IFRAME_BASE_URL[resolveIframeEnv(env)];
}

/** Timeout for postMessage requests (30 seconds) */
export const MESSAGE_TIMEOUT = 30 * 1000;

/** Miaoda 渠道标识默认值（用户可通过 config.common.channelType 覆盖） */
export const DEFAULT_CHANNEL_TYPE = 'MIAODA_CUI_SDK';
export const DEFAULT_ANONYMOUS_CHANNEL_TYPE = 'MIAODA_ANONYMOUS_CUI_SDK';

/** Allowed origins for postMessage (cui-iframe 的 origin) */
export const ALLOWED_ORIGINS = [
  IFRAME_ORIGIN.production,
  IFRAME_ORIGIN.staging,
  IFRAME_ORIGIN.boe,
  'http://localhost:3000',
  'http://localhost:5173',
  IFRAME_ORIGIN.development,
];
