import { IframeManager } from './iframe-manager';
import { AgentIframeManager } from './agent-iframe-manager';

import type {
  AgentSDKInitConfig,
  AgentSDKInstance,
  ChatPanel,
  WebSDKConfig,
} from './types/config';

/**
 * Initialize Aily Chat via iframe
 * This is the primary method for initializing the chat panel
 * @param root - Container element for the iframe
 * @param config - Configuration options
 * @returns ChatPanel instance for controlling the chat
 */
export async function initAilyChat(
  root: HTMLElement,
  config: WebSDKConfig
): Promise<ChatPanel> {
  const manager = new IframeManager(root, config);
  return manager.init();
}

/**
 * Initialize Agent Chat via iframe
 * @param root - Container element for the iframe
 * @param config - Agent SDK configuration
 * @returns Agent SDK instance for controlling the agent page
 */
export async function initAgentChat(
  root: HTMLElement,
  config: AgentSDKInitConfig
): Promise<AgentSDKInstance> {
  const manager = new AgentIframeManager(root, config);
  return manager.init();
}

