import { PARENT_ORIGIN_QUERY_KEY, getAgentIframeBaseURL } from './constants';
import { MessageBridge } from './message-bridge';

import type {
  AgentSDKInitConfig,
  AgentSDKInstance,
  AgentSDKRuntimeCustomContext,
} from './types/config';
import type {
  AgentReadyEventData,
  ParentContextMessageData,
  ParentContextResponseData,
} from './types/message';

/**
 * AgentIframeManager handles agent iframe creation and lifecycle.
 */
export class AgentIframeManager {
  private static readonly WARN_PREFIX = '[aily-web-sdk]';
  private iframe: HTMLIFrameElement | null = null;
  private readonly messageBridge: MessageBridge;
  private readonly config: AgentSDKInitConfig;
  private readonly root: HTMLElement;
  private readonly runtimeCustomContext: AgentSDKRuntimeCustomContext | null;
  private readonly contextVersion: string;
  private initialHandshakeCompleted = false;

  constructor(root: HTMLElement, config: AgentSDKInitConfig) {
    this.root = root;
    this.config = config;
    this.runtimeCustomContext = this.resolveRuntimeCustomContext(config);
    this.contextVersion = this.createContextVersion();
    this.messageBridge = new MessageBridge(getAgentIframeBaseURL());
  }

  async init(): Promise<AgentSDKInstance> {
    this.iframe = document.createElement('iframe');
    this.iframe.src = this.buildIframeURL();
    this.iframe.style.width = '100%';
    this.iframe.style.height = '100%';
    this.iframe.style.border = 'none';
    this.iframe.allow = 'microphone; clipboard-write';

    const readyPromise = this.waitForReady();
    this.messageBridge.onEvent('ready', this.handleSubsequentReady);
    this.messageBridge.attach(this.iframe);
    this.root.appendChild(this.iframe);

    try {
      const readyData = await readyPromise;
      await this.sendParentContext(readyData);
    } catch (error) {
      this.warn(
        'Agent SDK initialization encountered a non-blocking error. Initialization will continue without blocking the iframe lifecycle.',
        error
      );
    } finally {
      this.initialHandshakeCompleted = true;
    }

    return this.createAgentInstance();
  }

  async destroy(): Promise<void> {
    this.messageBridge.offEvent('ready', this.handleSubsequentReady);

    try {
      await this.messageBridge.send('destroy');
    } catch {
      // Ignore errors during destroy.
    }

    this.messageBridge.detach();
    this.removeIframe();
    this.initialHandshakeCompleted = false;
  }

  private buildIframeURL(): string {
    const baseURL = getAgentIframeBaseURL();
    const params = new URLSearchParams({
      channelToken: this.config.channelToken,
      [PARENT_ORIGIN_QUERY_KEY]: window.location.origin,
    });

    return `${baseURL}?${params.toString()}`;
  }

  private buildParentContext(): ParentContextMessageData {
    const parentContext: ParentContextMessageData = {
      parentOrigin: window.location.origin,
    };

    return parentContext;
  }

  private waitForReady(): Promise<AgentReadyEventData | undefined> {
    return new Promise((resolve, reject) => {
      const handleReady = (data: unknown) => {
        clearTimeout(timeout);
        this.messageBridge.offEvent('ready', handleReady);
        resolve(this.parseReadyEventData(data));
      };

      const timeout = setTimeout(() => {
        this.messageBridge.offEvent('ready', handleReady);
        reject(new Error('Iframe ready timeout'));
      }, 30000);

      this.messageBridge.onEvent('ready', handleReady);
    });
  }

  private readonly handleSubsequentReady = (data: unknown): void => {
    if (!this.initialHandshakeCompleted) {
      return;
    }

    void this.sendParentContext(this.parseReadyEventData(data)).catch(error => {
      this.warn(
        'Failed to re-send initParentContext after iframe ready event.',
        error
      );
    });
  };

  private async sendParentContext(
    readyData?: AgentReadyEventData
  ): Promise<void> {
    const payload = this.buildParentContextForReady(readyData);
    let response: ParentContextResponseData | undefined;

    try {
      response = await this.messageBridge.send<ParentContextResponseData>(
        'initParentContext',
        payload
      );
    } catch (error) {
      this.warn(
        'Failed to send initParentContext during initialization.',
        error
      );
      return;
    }

    if (!this.runtimeCustomContext) {
      return;
    }

    if (response?.accepted !== true) {
      this.warn(
        'Iframe rejected initParentContext custom context. Custom context will be ignored for this initialization.'
      );
      return;
    }

    if (
      payload.iframeSessionId &&
      response.iframeSessionId &&
      response.iframeSessionId !== payload.iframeSessionId
    ) {
      this.warn(
        'Iframe returned mismatched iframeSessionId. Custom context acknowledgement will be ignored.'
      );
      return;
    }

    if (
      payload.contextVersion &&
      response.contextVersion &&
      response.contextVersion !== payload.contextVersion
    ) {
      this.warn(
        'Iframe returned mismatched contextVersion. Custom context acknowledgement will be ignored.'
      );
    }
  }

  private buildParentContextForReady(
    readyData?: AgentReadyEventData
  ): ParentContextMessageData {
    const parentContext = this.buildParentContext();

    if (!this.runtimeCustomContext) {
      return parentContext;
    }

    if (!this.readySupportsRuntimeContext(readyData)) {
      this.warn(
        'Current iframe version does not support custom context initParentContext protocol. SDK initialization will continue without custom context.'
      );
      return parentContext;
    }

    return {
      ...parentContext,
      protocolVersion: 2,
      iframeSessionId: readyData.iframeSessionId,
      contextVersion: this.contextVersion,
      runtimeCustomContext: this.runtimeCustomContext,
    };
  }

  private readySupportsRuntimeContext(
    readyData?: AgentReadyEventData
  ): readyData is AgentReadyEventData & {
    protocolVersion: 2;
    iframeSessionId: string;
    needsContext: true;
  } {
    return (
      readyData?.protocolVersion === 2 &&
      Boolean(readyData.iframeSessionId) &&
      readyData.needsContext === true
    );
  }

  private parseReadyEventData(data: unknown): AgentReadyEventData | undefined {
    if (!this.isRecord(data)) {
      return undefined;
    }

    return data as AgentReadyEventData;
  }

  private resolveRuntimeCustomContext(
    config: AgentSDKInitConfig
  ): AgentSDKRuntimeCustomContext | null {
    let customParamsToken: string | undefined;
    if (config.customParamsToken !== undefined) {
      customParamsToken = config.customParamsToken.trim();
      if (!customParamsToken) {
        this.warn(
          'customParamsToken cannot be empty. SDK initialization will continue without custom context.'
        );
      }
    }

    if (config.customParams === undefined) {
      if (customParamsToken !== undefined) {
        return {
          customParamsToken,
        };
      }

      return null;
    }

    return {
      customParams: config.customParams,
      ...(customParamsToken !== undefined ? { customParamsToken } : {}),
    };
  }

  private isRecord(value: unknown): value is Record<string, unknown> {
    return typeof value === 'object' && value !== null && !Array.isArray(value);
  }

  private createContextVersion(): string {
    return `ctx-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  }

  private warn(message: string, error?: unknown): void {
    if (error === undefined) {
      console.warn(AgentIframeManager.WARN_PREFIX, message);
      return;
    }

    console.warn(AgentIframeManager.WARN_PREFIX, message, error);
  }

  private removeIframe(): void {
    if (this.iframe?.parentNode) {
      this.iframe.parentNode.removeChild(this.iframe);
    }

    this.iframe = null;
  }

  private createAgentInstance(): AgentSDKInstance {
    return {
      destroy: async () => {
        await this.destroy();
      },
    };
  }
}
