import { MESSAGE_TIMEOUT, ALLOWED_ORIGINS } from './constants';
import {
  MESSAGE_BIZ_ID,
  type IframeMessage,
  type IframeRequestMessage,
  type IframeResponseMessage,
  type IframeEventMessage,
  type IframeMessageType,
} from './types/message';
import { slardar } from '@lark-apaas/internal-slardar';

interface PendingRequest {
  resolve: (value: unknown) => void;
  reject: (reason: Error) => void;
  timer: ReturnType<typeof setTimeout>;
}

/**
 * MessageBridge handles postMessage communication between parent and iframe
 */
export class MessageBridge {
  private iframe: HTMLIFrameElement | null = null;
  private requestId = 0;
  private pendingRequests = new Map<number, PendingRequest>();
  private eventHandlers = new Map<string, ((data: unknown) => void)[]>();
  private targetOrigin: string;

  constructor(targetOrigin: string) {
    this.targetOrigin = new URL(targetOrigin).origin;
    this.handleMessage = this.handleMessage.bind(this);
  }

  /**
   * Attach to an iframe and start listening for messages
   */
  attach(iframe: HTMLIFrameElement): void {
    this.iframe = iframe;
    window.addEventListener('message', this.handleMessage);
  }

  /**
   * Detach from iframe and clean up
   */
  detach(): void {
    window.removeEventListener('message', this.handleMessage);
    this.iframe = null;
    // Clear all pending requests
    this.pendingRequests.forEach(({ reject }) => {
      reject(new Error('MessageBridge detached'));
    });
    this.pendingRequests.clear();
  }

  /**
   * Send a message to the iframe and wait for response
   */
  send<T = unknown>(type: IframeMessageType, data?: unknown): Promise<T> {
    return new Promise((resolve, reject) => {
      if (!this.iframe?.contentWindow) {
        reject(new Error('Iframe not attached'));
        return;
      }

      this.requestId += 1;
      const id = this.requestId;
      const message: IframeRequestMessage = {
        messageBizId: MESSAGE_BIZ_ID,
        id,
        type,
        data,
        timestamp: Date.now(),
        isRequest: true,
      };

      const timer = setTimeout(() => {
        this.pendingRequests.delete(id);
        const error = new Error(`Message timeout: ${type}`);
        slardar.captureException(error, {
          source: 'aily-web-sdk',
          module: 'message-bridge',
          messageType: type,
        });
        reject(error);
      }, MESSAGE_TIMEOUT);

      this.pendingRequests.set(id, {
        resolve: resolve as (value: unknown) => void,
        reject,
        timer,
      });

      this.iframe.contentWindow.postMessage(message, this.targetOrigin);
    });
  }

  /**
   * Register an event handler
   */
  onEvent(eventName: string, handler: (data: unknown) => void): void {
    const handlers = this.eventHandlers.get(eventName) || [];
    handlers.push(handler);
    this.eventHandlers.set(eventName, handlers);
  }

  /**
   * Remove an event handler
   */
  offEvent(eventName: string, handler: (data: unknown) => void): void {
    const handlers = this.eventHandlers.get(eventName) || [];
    const index = handlers.indexOf(handler);
    if (index > -1) {
      handlers.splice(index, 1);
      this.eventHandlers.set(eventName, handlers);
    }
  }

  private handleMessage(event: MessageEvent<IframeMessage>): void {
    // Validate origin
    if (!ALLOWED_ORIGINS.includes(event.origin)) {
      return;
    }

    const { data } = event;

    // Validate message format
    if (data?.messageBizId !== MESSAGE_BIZ_ID) {
      return;
    }

    // Handle response messages
    if (this.isResponseMessage(data)) {
      const pending = this.pendingRequests.get(data.id);
      if (pending) {
        clearTimeout(pending.timer);
        this.pendingRequests.delete(data.id);

        if (data.error) {
          const error = new Error(data.error.message);
          slardar.captureException(error, {
            source: 'aily-web-sdk',
            module: 'message-bridge',
            errorCode: data.error.code,
          });
          pending.reject(error);
        } else {
          pending.resolve(data.data);
        }
      }
    }

    // Handle event messages
    if (this.isEventMessage(data)) {
      const handlers = this.eventHandlers.get(data.eventName) || [];
      handlers.forEach(handler => {
        try {
          handler(data.data);
        } catch {
          // Ignore handler errors
        }
      });
    }
  }

  private isResponseMessage(
    data: IframeMessage
  ): data is IframeResponseMessage {
    return 'isResponse' in data && data.isResponse === true;
  }

  private isEventMessage(data: IframeMessage): data is IframeEventMessage {
    return data.type === 'event';
  }
}
