const MOBILE_BREAKPOINT = 768;

type DeviceType = 'pc' | 'mobile';
type DeviceChangeCallback = (device: DeviceType) => void;

/**
 * 设备类型自动检测器
 *
 * 使用 matchMedia + 768px 断点检测设备类型，与 miaoda useIsMobile 逻辑一致。
 * 检测在宿主页面（而非 iframe）中执行，结果通过 postMessage 推送给 iframe。
 */
export class DeviceDetector {
  private mediaQuery: MediaQueryList;
  private currentDevice: DeviceType;
  private callback: DeviceChangeCallback | null = null;
  private handleChange: (() => void) | null = null;

  constructor() {
    this.mediaQuery = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`);
    this.currentDevice = window.innerWidth < MOBILE_BREAKPOINT ? 'mobile' : 'pc';
  }

  getDevice(): DeviceType {
    return this.currentDevice;
  }

  observe(callback: DeviceChangeCallback): void {
    this.callback = callback;
    this.handleChange = () => {
      const newDevice: DeviceType = window.innerWidth < MOBILE_BREAKPOINT ? 'mobile' : 'pc';
      if (newDevice !== this.currentDevice) {
        this.currentDevice = newDevice;
        this.callback?.(newDevice);
      }
    };
    this.mediaQuery.addEventListener('change', this.handleChange);
  }

  destroy(): void {
    if (this.handleChange) {
      this.mediaQuery.removeEventListener('change', this.handleChange);
      this.handleChange = null;
    }
    this.callback = null;
  }
}
